                    "_value": "Diabetes Type 2",
                    "type": "text"
                },
                "link": [
                    {
                        "href": "https://medlineplus.gov/diabetestype2.html?utm_source=mplusconnect&utm_medium=service",
                        "rel": "alternate"
                    }
